# Re-enable Multi-Plane Overlay (MPO) Write-Host "Re-enabling Multi-Plane Overlay (MPO)..." -ForegroundColor Cyan Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\Dwm" -Name "OverlayTestMode" -ErrorAction SilentlyContinue Write-Host "Multi-Plane Overlay (MPO) has been re-enabled." -ForegroundColor Green Write-Host "A restart may be required for changes to take effect." -ForegroundColor Yellow